# The demo output is a square spiral of 3s. Input has single 3 at (4,5), output draws a spiral.
# Spiral: seems like nested rectangles sharing center region. Pattern: it's a spiral going...
# Outer boundary rows0 and 8, cols1 and 9? Actually looks like a spiral arm sequence.
# Simpler hypothesis: draw nested square spirals expanding from the 3's cell, filling until grid edge, skipping last row?
# Row 10 fully 3 — bottom row. Column? None full except bottom.
# Hypothesis: spiral starting at (4,5) going in directions with arm lengths growing? Let's map connectivity.
def comp(g,color=3):
    seen=set(); out=[]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j]==color and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); c=[]
                while st:
                    a,b=st.pop(); c.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<len(g) and 0<=y<len(g[0]) and g[x][y]==color and (x,y) not in seen:
                            seen.add((x,y)); st.append((x,y))
                out.append(sorted(c))
    return out
cs=comp(do_)
for c in cs: print(len(c), c[:5], '...' if len(c)>5 else '', c[-3:])

