def walk(S,start):
    seen={start}; st=[start]; order=[]
    while st:
        p=st.pop(); order.append(p)
        for a,b in ((1,0),(-1,0),(0,1),(0,-1)):
            q=(p[0]+a,p[1]+b)
            if q in S and q not in seen:
                seen.add(q); st.append(q)
    return order
